// --- random per-key-dim gates vs the K3 oracle (the core check) ----------
TEST(KdaK3Chunked, MatchesNaiveOracleRandomGates) {
  struct Cfg { int B, H, S, D, cs; };
  const Cfg cfgs[] = {
      {1, 1, 64, 16, 16},    // 1 chunk
      {1, 1, 64, 16, 32},    // 2 chunks
      {1, 1, 64, 16, 64},    // 1 chunk, cs==S
      {1, 1, 64, 32, 16},    // 4 chunks, D=32
      {1, 1, 64, 64, 32},    // 2 chunks, D=64
      {1, 2, 64, 64, 64},    // 1 chunk, H=2
      {1, 1, 128, 128, 32},  // 4 chunks, D=128
  };
  std::mt19937 rng(20260909);
  for (const auto& c : cfgs) {
    const size_t n = (size_t)c.B * c.H * c.S;
    std::vector<float> q(n * c.D), k(n * c.D), v(n * c.D),
        g(n * c.D), beta(n);
    for (size_t i = 0; i < n * c.D; ++i) {
      q[i] = (rng() % 2001 - 1000) / 100.0f;   // [-10, 10]
      k[i] = (rng() % 2001 - 1000) / 100.0f;
      v[i] = (rng() % 2001 - 1000) / 100.0f;
      // per-key-dim gate in (0,1]: strictly positive so log(g) is finite
      g[i] = (rng() % 100 + 1) / 100.0f;       // (0.01, 1.0]
    }
    for (size_t i = 0; i < n; ++i) beta[i] = (rng() % 100 + 1) / 100.0f;
    // L2-normalise k (as the caller does); q left raw (oracle doesn't rescale q)
    for (size_t i = 0; i < n; ++i) {
      float* ki = k.data() + i * c.D;
      float nrm = std::sqrt(dot(ki, ki, c.D)) + 1e-12f;
      for (int d = 0; d < c.D; ++d) ki[d] /= nrm;
    }
    std::vector<float> naive(n * c.D, 0.0f), chunked(n * c.D, 0.0f);
    kda_naive_delta_rule_fwd_cpu(q.data(), k.data(), v.data(), g.data(),
                                 beta.data(), naive.data(),
                                 c.B, c.H, c.S, c.D);
    k3_delta_rule_fwd(q.data(), k.data(), v.data(), g.data(), beta.data(),
                      chunked.data(), c.B, c.H, c.S, c.D, c.cs);
    float max_abs = 0.0f, max_rel = 0.0f;
    for (size_t i = 0; i < n * c.D; ++i) {
      const float e = std::fabs(naive[i] - chunked[i]);
      if (e > max_abs) max_abs = e;
      if (std::fabs(naive[i]) > 1e-9f) {
        float r = e / std::fabs(naive[i]);
        if (r > max_rel) max_rel = r;
      }
    }
    std::printf("  B=%d H=%d S=%d D=%d cs=%d  max_abs=%.6f max_rel=%.6f\n",
                c.B, c.H, c.S, c.D, c.cs, max_abs, max_rel);
    // The naive oracle is O(S*D^2) fp32 with a different summation order from
    // the chunked path (per-token matmul vs gate-product + triangular solve),
    // so allow fp32 round-off, not bit-equality.
    EXPECT_LT(max_rel, 2e-4f);
  }
}

