// =====================================================================
// Affine (WY) reformulation — the exact op sequence the HIP chunked
// kernel (#70) implements. Same math as the forward-substitution path
// above, restructured so that everything depending on C_{c-1} is a plain
// GEMM and all chunk-local work (grams, triangular inverse, Ainv/Bn
// products) is computed WITHOUT the inter state — i.e. fully parallel
// across chunks. Within-chunk t = 0..C-1, L_t[k] = per-column log-cumsum:
//
//   M[t][j] = b_j * sum_k G_{j+1,t}[k] k_j[k] k_t[k]     (j<t, strict tril)
//   N[t][j] = b_j * sum_k G_{j+1,t}[k] k_j[k] q_t[k]     (j<=t, incl diag)
//   A = I + tril(M,-1);  Ainv = A^{-1};  Bn = N
//   Kgw[t][k] = exp(L_t[k]) k_t[k];  Qgw[t][k] = exp(L_t[k]) q_t[k]
//   Kgb[t][k] = b_t exp(L_end[k]-L_t[k]) k_t[k];  diagG[k] = exp(L_end[k])
//   U_v = Ainv v;  W = Ainv Kgw;  T = Bn U_v;  P = Bn W;  Opar = Qgw - P
//   ---- serial state pass (rowblock-splittable over v) ----
//   u = U_v - W C^T;  o = T + Opar C^T
//   C = diagG (.) C + Kgb^T u
//
// All gate factors are products of gates in (0,1], so every exp() argument
// is <= 0: values live in (0,1], underflow degrades gracefully to 0, and
// there is no overflow anywhere. The output identity uses associativity
// o = T + (Qgw - P) C^T, which is why Opar can be precomputed chunk-locally.
// =====================================================================
void k3_wy_chunked_fwd(const float* q, const float* k, const float* v,
                       const float* g, const float* beta, float* out,
                       int B, int H, int S, int D, int cs) {
  const int nc = (S + cs - 1) / cs;
  std::vector<float> L((size_t)cs * D);
  std::vector<float> M((size_t)cs * cs), N((size_t)cs * cs), Ainv((size_t)cs * cs);
  std::vector<float> Kgw((size_t)cs * D), U_v((size_t)cs * D), W((size_t)cs * D),
      T((size_t)cs * D), P((size_t)cs * D), Opar((size_t)cs * D),
      Kgb((size_t)cs * D), diagG(D), u((size_t)cs * D);
  std::vector<float> C((size_t)D * D, 0.0f);
  for (int b = 0; b < B; ++b)
  for (int h = 0; h < H; ++h) {
    std::fill(C.begin(), C.end(), 0.0f);
    for (int c = 0; c < nc; ++c) {
      const int t0 = c * cs;
      const int len = (S - t0 < cs) ? (S - t0) : cs;
      // per-column within-chunk inclusive log-cumsum (tail chunk: stop at len)
      for (int kk = 0; kk < D; ++kk) {
        float acc = 0.0f;
        for (int t = 0; t < len; ++t) {
          acc += log_gate(g[((size_t)(b * H + h) * S + t0 + t) * D + kk]);
          L[(size_t)t * D + kk] = acc;
        }
      }
      const int lend = len - 1;
      // grams M (strict) and N (incl diag), beta folded in
      for (int t = 0; t < len; ++t)
      for (int j = 0; j <= t; ++j) {
        const float* kj = k + ((size_t)(b * H + h) * S + t0 + j) * D;
        const float* kt = k + ((size_t)(b * H + h) * S + t0 + t) * D;
        const float* qt = q + ((size_t)(b * H + h) * S + t0 + t) * D;
        const float* Lj = L.data() + (size_t)j * D;
        const float* Lt = L.data() + (size_t)t * D;
        float mk = 0.0f, nk = 0.0f;
        for (int kk = 0; kk < D; ++kk) {
          const float gw = std::exp(Lt[kk] - Lj[kk]);   // G_{j+1,t}[k]
          mk += gw * kj[kk] * kt[kk];
          nk += gw * kj[kk] * qt[kk];
        }
        const float bj = beta[(size_t)(b * H + h) * S + t0 + j];
        N[(size_t)t * cs + j] = bj * nk;
        if (j < t) M[(size_t)t * cs + j] = bj * mk; else M[(size_t)t * cs + j] = 0.0f;
      }
      // Ainv = (I + tril(M,-1))^{-1} by forward substitution, column-wise
      for (int j = 0; j < len; ++j)
      for (int t = 0; t < len; ++t) {
        float x = (t == j) ? 1.0f : 0.0f;
        if (t > j) {
          float s = 0.0f;
          for (int l = j; l < t; ++l) s -= M[(size_t)t * cs + l] * Ainv[(size_t)l * cs + j];
          x = s;
        }
        Ainv[(size_t)t * cs + j] = x;
      }
      // chunk-local artifacts
      for (int t = 0; t < len; ++t) {
        const float* kt = k + ((size_t)(b * H + h) * S + t0 + t) * D;
        const float* qt = q + ((size_t)(b * H + h) * S + t0 + t) * D;
        const float* vt = v + ((size_t)(b * H + h) * S + t0 + t) * D;
        const float* Lt = L.data() + (size_t)t * D;
        const float bt = beta[(size_t)(b * H + h) * S + t0 + t];
        for (int kk = 0; kk < D; ++k) {
