          Kgb[t*D+kk] = beta[t0+t]*exp(L[lend*D+kk]-L[t*D+kk])*k[t0+t][kk]
        diagG[kk] = exp(L[lend*D+kk])   // inside kk loop
      // GEMMs: U_v = Ainv@v; W = Ainv@Kgw; T = Bn@U_v; P = Bn@W; Opar = Qgw - P
      for t<len, d<D: s = 0; for j<len: s += Ainv[t*cs+j]*v[(t0+j)*D+d]; U_v[t*D+d]=s
      for t<len, d<D: s = 0; for j<len: s += Ainv[t*cs+j]*Kgw[j*D+d]; W[t*D+d]=s
      for t<len, d<D: s = 0; for j<=t: s += N[t*cs+j]*U_v[j*D+d]; T[t*D+d]=s
      for t<len, d<D: s = 0; for j<=t: s += N[t*cs+j]*W[j*D+d]; P[t*D+d]=s; Opar[t*D+d] = Qgw[t*D+d]-s
      // serial state pass
      for t<len, v<D: s = U_v[t*D+v]; for kk: s -= W[t*D+kk]*C[v*D+kk]; u[t*D+v]=s
      for t<len, v<D: s = T[t*D+v]; for kk: s += Opar[t*D+kk]*C[v*D+kk]; out[(t0+t)*D+v]=s
      for v<D, kk<D: s = diagG[kk]*C[v*D+kk]; for t<len: s += Kgb[t*D+kk]*u[t*D+v]; C[v*D+kk]=s
}
