+447         P[(size_t)t * D + d] = sp;
+448         Opar[(size_t)t * D + d] = Qgw[(size_t)t * D + d] - sp;
+449       }
+450       // serial state pass (rowblock-splittable: only row v of C appears)
+451       for (int t = 0; t < len; ++t)
+452       for (int d = 0; d < D; ++d) {
+453         float s = U_v[(size_t)t * D + d];
+454         for (int kk = 0; kk < D; ++kk)
+455           s -= W[(size_t)t * D + kk] * C[(size_t)d * D + kk];
