+468         for (int t = 0; t < len; ++t)
+469           s += Kgb[(size_t)t * D + kk] * u[(size_t)t * D + d];
+470         C[(size_t)d * D + kk] = s;
+471       }
+472     }
+473   }
+474   (void)row0;
+475 }
