+      EXPECT_NEAR(wy[i], naive[i], 1e-4f);
+    }
+    std::printf("  B=%d H=%d S=%d D=%d cs=%d  wy max_abs=%.6f\n",
+                c.B, c.H, c.S, c.D, c.cs, max_abs);
+  }
+}
