+434   // One warp per block, lane = column; the whole column lives in the
+435   // lane's registers so the forward substitution is barrier-free.
+436   {
+437     const int w = tid / 32;
+438     if (w < 4) {
+439       const int lane = tid % 32;
+440       if (lane < 16) {
+441         const int j = lane, br = w * 16;
+442         float col[16];
+443         for (int i = j; i < 16; ++i) {
+444           float x = (i == j) ? 1.0f : 0.0f;
+445           const float* arow = sM + (size_t)(br + i) * kCs + br;
+446           for (int l = j; l < i; ++l) x -= arow[l] * col[l];
+447           col[i] = x;
+448         }
+449         for (int i = j; i < 16; ++i)
+450           sM[(size_t)(br + i) * kCs + br + j] = col[i];
+451       }
+452     }
+453   }
+454   __syncthreads();
+455 
+456   // phase 2b: off-diagonal inverse blocks, level by level:
+457   //   Ainv[r][s] = -Ainv[r][r] @ ( sum_{m=s..r-1} M[r][m] @ Ainv[m][s] )
+458   // Level r only reads M blocks of row r (never overwritten) and Ainv
+459   // blocks finalized at earlier levels, so two barrier rounds per level
+460   // suffice: (a) X tiles into sTMP, (b) the -Ainv[r][r] @ X product back
+461   // into sM block (r,s) — which destroys M[r][s], unused from here on.
+462   for (int r = 1; r < 4; ++r) {
+463     for (int s = 0; s < r; ++s)
+464       for (int cell = tid; cell < 256; cell += kTh) {
+465         const int i = cell / 16, jj = cell % 16;
+466         float x = 0.0f;
+467         for (int m = s; m < r; ++m)
+468           for (int l = 0; l < 16; ++l)
+469             x += sM[(size_t)(r * 16 + i) * kCs + m * 16 + l] *
+470                  sM[(size_t)(m * 16 + l) * kCs + s * 16 + jj];
+471         sTMP[s * 256 + cell] = x;
+472       }
+473     __syncthreads();
+474     for (int s = 0; s < r; ++s)
+475       for (int cell = tid; cell < 256; cell += kTh) {
+476         const int i = cell / 16, jj = cell % 16;
+477         float x = 0.0f;
+478         for (int l = 0; l < 16; ++l)
+479           x += sM[(size_t)(r * 16 + i) * kCs + r * 16 + l] *
+480                sTMP[s * 256 + l * 16 + jj];
+481         sM[(size_t)(r * 16 + i) * kCs + s * 16 + jj] = -x;
+482       }
+483     __syncthreads();
+484   }
+485 
+486   // phase 3: U_v = Ainv @ v ; W = Ainv @ Kgw   (dot over j; Ainv row in LDS)
+487   for (int i = tid; i < kCs * D; i += kTh) {
+488     const int t = i / D, d = i % D;
+489     const float* arow = sM + (size_t)t * kCs;
+490     float sv = 0.0f, sw = 0.0f;
+491     for (int j = 0; j < kCs; ++j) {
+492       const float a = arow[j];
+493       sv += a * v[(tok + j) * D + d];
+494       sw += a * Kgw[lb + (size_t)j * D + d];
+495     }
+496     U_v[lb + i] = sv;
+497     W[lb + i]  = sw;
+498   }
+499   __syncthreads();   // orders the gmem U_v/W writes for phase 4 readers
+500 
+501   // phase 4: T = N @ U_v ; Opar = Qgw - N @ W   (N row in LDS; tril-incl)
+502   for (int i = tid; i < kCs * D; i += kTh) {
+503     const int t = i / D, d = i % D;
+504     const float* nrow = sN + (size_t)t * kCs;
+505     float st = 0.0f, sp = 0.0f;
+506     for (int j = 0; j <= t; ++j) {
+507       const float n = nrow[j];
+508       st += n * U_v[lb + (size_t)j * D + d];
+509       sp += n * W[lb + (size_t)j * D + d];
+510     }
+511     T[lb + i]    = st;
+512     Opar[lb + i] = Qgw[lb + i] - sp;
+513   }
+514 }
+515 
+516 // ---- (3) serial state pass: u/o/C per chunk, rowblock-split over v -------
+517 template <int D, int Rb>
+518 __global__ void kda_k3_state_kernel(
+519     const float* __restrict__ U_v, const float* __restrict__ W,
+520     const float* __restrict__ T, const float* __restrict__ Opar,
+521     const float* __restrict__ Kgb, const float* __restrict__ diagG,
+522     float* __restrict__ state, float* __restrict__ out,
+523     int nc, int S) {
+524   const int bh = blockIdx.y;
+525   const int v0 = blockIdx.x * Rb;      // this block's state rows [v0, v0+Rb)
+526   const int tid = threadIdx.x;
+527   const size_t lb0 = (size_t)bh * nc;
+528   __shared__ float sC[Rb * D];         // C rows v0..v0+Rb (all k)
+529   __shared__ float sU[kCs * Rb];       // u tile for the current chunk
+530   float* Cst = state + (size_t)bh * D * D + (size_t)v0 * D;
+531 
+532   for (int i = tid; i < Rb * D; i += kTh) sC[i] = Cst[i];   // initial state
+533   __syncthreads();
+534 
+535   for (int c = 0; c < nc; ++c) {
+536     const size_t lb = (lb0 + c) * kCs * D;
+537     // u = U_v - W C^T      u[t][v] = U_v[t][v] - sum_k W[t][k] C[v][k]
+538     for (int i = tid; i < kCs * Rb; i += kTh) {
+539       const int t = i / Rb, vv = i % Rb;
+540       const float* wrow = W + lb + (size_t)t * D;
+541       const float* crow = sC + vv * D;
+542       float s = U_v[lb + (size_t)t * D + v0 + vv];
+543       for (int e = 0; e < D; ++e) s -= wrow[e] * crow[e];
+544       sU[i] = s;
+545     }
+546     __syncthreads();   // sU complete before o/C read it
+547     // o = T + Opar C^T    (uses the OLD C = C_{c-1})
+548     for (int i = tid; i < kCs * Rb; i += kTh) {
+549       const int t = i / Rb, vv = i % Rb;
+550       const float* orow = Opar + lb + (size_t)t * D;
+551       const float* crow = sC + vv * D;
+552       float s = T[lb + (size_t)t * D + v0 + vv];
+553       for (int e = 0; e < D; ++e) s += orow[e] * crow[e];
+554       out[((size_t)bh * S + c * kCs + t) * D + v0 + vv] = s;
+555     }
+556     __syncthreads();   // all o readers done with old C before C is updated
+557     // C = diagG (.) C + Kgb^T u
+558     //    C[v][k] = diagG[k] C[v][k] + sum_t Kgb[t][k] u[t][v]
+559     const float* dg = diagG + (lb0 + c) * D;
+560     for (int i = tid; i < Rb * D; i += kTh) {
+561       const int vv = i / D, e = i % D;
+562       float s = dg[e] * sC[i];
+563       for (int t = 0; t < kCs; ++t)
+564         s += Kgb[lb + (size_t)t * D + e] * sU[t * Rb + vv];
+565       sC[i] = s;
+566     }
+567     __syncthreads();   // sC updated before the next chunk's u/o read it
+568   }
+569 
+570   for (int i = tid; i < Rb * D; i += kTh) Cst[i] = sC[i];  // final state
+571 }
+572 
+573 namespace {
+574 // Scratch float count for the chunked path: L, Kgw, Qgw, Kgb, U_v, W, T,
+575 // Opar are [B,H,nc,cs,D] (= B*H*S*D each); diagG is [B,H,nc,D].
+576 size_t chunked_scratch_floats(int B, int H, int S, int D) {
+577   const size_t ncsd = (size_t)B * H * S * D;
+578   const size_t nc = (size_t)S / kCs;
+579   return 8ull * ncsd + (size_t)B * H * nc * D;
+580 }
+581 
+582 template <int D>
+583 void launch_chunked(const float* q, const float* k, const float* v,
+584                     const float* g, const float* beta, float* state,
+585                     float* out, float* scratch, int B, int H, int S) {
+586   const int nc = S / kCs;
+587   const size_t ncsd = (size_t)B * H * S * D;      // per-array float count
+588   float* L    = scratch;
+589   float* Kgw  = L + ncsd;         float* Qgw = Kgw + ncsd;
+590   float* Kgb  = Qgw + ncsd;       float* dgG = Kgb + ncsd;
+591   float* U_v  = dgG + (size_t)B * H * nc * D;
+592   float* W    = U_v + ncsd;       float* T   = W + ncsd;
+593   float* Opar = T + ncsd;
+594   const dim3 gchunk(B * H, nc);
+595   kda_k3_cumsum_kernel<<<gchunk, kTh>>>(g, L, nc, S, D);
+596   kda_k3_local_kernel<D><<<gchunk, kTh>>>(q, k, v, beta, L, Kgw, Qgw, Kgb,
+597                                          dgG, U_v, W, T, Opar, nc, S);
+598   constexpr int Rb = (D <= 32) ? D : 32;          // state rows per block
+599   const dim3 gstate(D / Rb, B * H);
+600   kda_k3_state_kernel<D, Rb><<<gstate, kTh>>>(U_v, W, T, Opar, Kgb, dgG,
+601                                               state, out, nc, S);
+602   hipDeviceSynchronize();   // match the cooperative launcher's convention
+603 }
+604 }  // namespace
+605 
+606 void kda_delta_rule_fwd_chunked_with_scratch(
+607     const float* q, const float* k, const float* v, const float* g,
+608     const float* beta, float* state, float* out, float* scratch,
+609     int B, int H, int S, int D, int chunk_size) {
+610   if (B == 0 || H == 0 || S == 0) return;
+611   if (chunk_size != kCs || S % kCs != 0 || D > 128) {
+612     std::fprintf(stderr,
+613                  "kda_delta_rule_fwd_chunked_with_scratch: requires "
+614                  "chunk_size==64, S%%64==0, D<=128 (got cs=%d S=%d D=%d)\n",
+615                  chunk_size, S, D);
+616     return;
+617   }
+618   if (D <= 16)      launch_chunked<16>(q, k, v, g, beta, state, out, scratch, B, H, S);
+619   else if (D <= 32) launch_chunked<32>(q, k, v, g, beta, state, out, scratch, B, H, S);
+620   else if (D <= 64) launch_chunked<64>(q, k, v, g, beta, state, out, scratch, B, H, S);
+621   else              launch_chunked<128>(q, k, v, g, beta, state, out, scratch, B, H, S);
+622 }
+623 
+624 void kda_delta_rule_fwd_chunked(const float* q, const float* k,
+625                                 const float* v, const float* g,
+626                                 const float* beta, float* out,
+627                                 int B, int H, int S, int D, int chunk_size) {
+628   if (B == 0 || H == 0 || S == 0) return;
+629   float* state = nullptr;
+630   hipMalloc(&state, (size_t)B * H * D * D * sizeof(float));
+631   hipMemsetAsync(state, 0, (size_t)B * H * D * D * sizeof(float), 0);
+632   float* scratch = nullptr;
+633   const size_t sf = chunked_scratch_floats(B, H, S, D);
+634   hipMalloc(&scratch, sf * sizeof(float));
+635   kda_delta_rule_fwd_chunked_with_scratch(q, k, v, g, beta, state, out,
+636                                           scratch, B, H, S, D, chunk_size);
+637   hipFree(state);
+638   hipFree(scratch);
+639 }
+640 
 318 }  // namespace vkernels::kernels::hip
