```cpp
  // phase 1: gate-weighted grams; one WARP per (t,j) pair, lanes over k
  // (coalesced 128 B requests), warp-shuffle reduction.
  const int warp = tid / 32, lane = tid % 32;
  const int n_pairs = kCs * (kCs + 1) / 2;
  for (int p = warp; p < n_pairs; p += kTh / 32) {
    int t = 0, rem = p;
    while (rem > t) { rem -= t + 1; ++t; }
    const int j = rem;
    float mk = 0.0f, nk = 0.0f;
    for (int e0 = 0; e0 < D; e0 += 32) {
      const int e = e0 + lane;              // lane-strided, coalesced
      float kjv = 0.f, ktv = 0.f, qtv = 0.f, Ljv = 0.f, Ltv = 0.f;
      if (e < D) {
        kjv = k[(tok + j) * D + e];
        ktv = k[(tok + t) * D + e];
        qtv = q[(tok + t) * D + e];
        Ljv = L[lb + (size_t)j * D + e];
        Ltv = L[lb + (size_t)t * D + e];
      }
      const float gw = (e < D) ? expf(Ltv - Ljv) : 0.0f;
      mk += gw * kjv * ktv;
      nk += gw * kjv * qtv;
    }
    #pragma unroll
    for (int off = 16; off > 0; off >>= 1) {
      mk += __shfl_xor_sync(0xffffffffu, mk, off);
      nk += __shfl_xor_sync(0xffffffffu, nk, off);
    }
    if (lane == 0) {
      const float bj = beta[tok + j];
      sN[(size_t)t * kCs + j] = bj * nk;
      if (j < t) sM[(size_t)t * kCs + j] = bj * mk;
    }
  }
```
