      while (rem > t) { rem -= t + 1; ++t; }
      const int j = rem;
      const float4* kj4 = (const float4*)(k + (tok + j) * D);
      const float4* kt4 = (const float4*)(k + (tok + t) * D);
      const float4* qt4 = (const float4*)(q + (tok + t) * D);
