gram_kernel = '''// ---- (2a) gate-weighted grams M/N — LDS-staged, quarter by quarter -----
// The gram dots re-read k/q/L rows ~cs times each; done straight from
// gmem that is L2-latency-bound (measured ~310 us/block even at 512
// threads — dependent loads, poor ILP through the pair decode). Instead
// stage k/q/L tiles for one quarter of the key dim in LDS (3 x cs x D/4
// floats; 24 KB at D=128, fits beside the 32 KB M/N accumulators), so
// every gram read is an LDS hit and the phase becomes SFU (exp) bound.
// M/N land in gmem ([B,H,nc,cs,cs] each) for the (2b) kernel.
template <int D>
__global__ void kda_k3_gram_kernel(
    const float* __restrict__ q, const float* __restrict__ k,
    const float* __restrict__ beta, const float* __restrict__ L,
    float* __restrict__ M, float* __restrict__ N,
    int nc, int S) {
  const int bh = blockIdx.x, c = blockIdx.y, tid = threadIdx.x;
  const int t0 = c * kCs;
  const size_t tok = (size_t)bh * S + t0;
  const size_t lb  = ((size_t)bh * nc + c) * kCs * D;
  const size_t lbq = ((size_t)bh * nc + c) * kCs * kCs;   // M/N chunk base
  constexpr int DQ  = D / 4;      // key-dims staged per pass (D multiple 16)
  constexpr int DQ4 = DQ / 4;     // float4 groups per staged row

  __shared__ float sM[kCs * kCs];
  __shared__ float sN[kCs * kCs];
  __shared__ float sk[kCs * DQ];  // staged quarter tiles
  __shared__ float sq[kCs * DQ];
  __shared__ float sL[kCs * DQ];

  for (int i = tid; i < kCs * kCs; i += kThL) { sM[i] = 0.0f; sN[i] = 0.0f; }
  __syncthreads();

  for (int h = 0; h < 4; ++h) {                   // quarter h of the key dim
    // stage k/q/L rows for this quarter (coalesced float4 copies)
    for (int i = tid * 4; i < kCs * DQ; i += kThL * 4) {
      const int t = i / DQ, e = i % DQ;
      const int g = h * DQ + e;                  // global key dim
      *(float4*)(sk + i) = *(const float4*)(k + (tok + t) * D + g);
      *(float4*)(sq + i) = *(const float4*)(q + (tok + t) * D + g);
      *(float4*)(sL + i) = *(const float4*)(L + lb + (size_t)t * D + g);
    }
    __syncthreads();
    // one warp per (t,j) pair, lanes over the quarter's float4 groups
    const int warp = tid / 32, lane = tid % 32;
    const int n_pairs = kCs * (kCs + 1) / 2;
    for (int pr = warp; pr < n_pairs; pr += kThL / 32) {
      int t = 0, rem = pr;
      while (rem > t) { rem -= t + 1; ++t; }
      const int j = rem;
      const float4* kj4 = (const float4*)(sk + (size_t)j * DQ);
      const float4* kt4 = (const float4*)(sk + (size_t)t * DQ);
      const float4* qt4 = (const float4*)(sq + (size_t)t * DQ);
      const float4* Lj4 = (const float4*)(sL + (size_t)j * DQ);
      const float4* Lt4 = (const float4*)(sL + (size_t)t * DQ);
      float mk = 0.0f, nk = 0.0f;
      #pragma unroll
      for (int e4 = 0; e4 < DQ4; ++e4) {
        const int e = lane + e4 * 32;            // lane-strided float4
        const float4 a = *(const float4*)((const char*)kj4 + (size_t)e * 16);
        const float4 b = *(const float4*)((const char*)kt4 + (size_t)e * 16);
        const float4 cc = *(const float4*)((const char*)qt4 + (size_t)e * 16);
        const float4 lj = *(const float4*)((const char*)Lj4 + (size_t)e * 16);
        const float4 lt = *(const float4*)((const char*)Lt4 + (size_t)e * 16);
        const float4 gw = {expf(lt.x - lj.x), expf(lt.y - lj.y),
                           expf(lt.z - lj.z), expf(lt.w - lj.w)};
        mk += gw.x * a.x * b.x + gw.y * a.y * b.y + gw.z * a.z * b.z +
              gw.w * a.w * b.w;
        nk += gw.x * a.x * cc.x + gw.y * a.y * cc.y + gw.z * a.z * cc.z +
              gw.w * a.w * cc.w;
      }
      #pragma unroll
      for (int off = 16; off > 0; off >>= 1) {
        mk += __shfl_xor(mk, off);
        nk += __shfl_xor(nk, off);
      }
      if (lane == 0) {
        const float bj = beta[tok + j];
        sN[(size_t)t * kCs + j] += bj * nk;
        if (j < t) sM[(size_t)t * kCs + j] += bj * mk;
      }
    }
    __syncthreads();
  }

  for (int i = tid; i < kCs * kCs; i += kThL) {
    M[lbq + i] = sM[i];
    N[lbq + i] = sN[i];
  }
}

