// vkernels/kernels/glm_moe.hip
//
// GLM block-FP8 expert primitives on gfx942 (issue #64). Device
// counterpart of glm_moe.cpp — see glm_moe.hpp for the format contract.
//
// glm_fp8_block_gemv — decode-fused E4M3FN GEMV for decode (M = 1/2):
//   * one 256-thread block owns 32 output rows (8 warps x 4 rows);
//     128-scale-block membership is computed per row, so any N % 128 == 0
//     works without alignment constraints between warps and scale blocks.
//   * the bf16 activations are staged in LDS as fp32 once per block and
//     reused by every row the block owns (x is tiny next to the weights).
//   * each lane streams one uint32 = 4 E4M3FN codes per 128-wide scale
//     segment (fully coalesced 128 B per warp per segment), decodes with
//     bit assembly (normals/NaN) or direct arithmetic (subnormals), and
//     accumulates in fp32; one warp shuffle reduction and one
//     round-to-nearest-even bfloat16 store per row.
// The op is memory-bound on the weight bytes at M=1 (AI ~ 2 FLOP/byte):
// no dequantized buffer is ever materialized.
#include <cstdint>

#include "vkernels/kernels/glm_moe.hpp"

#if VKERNELS_HAS_HIP

namespace vkernels::kernels::hip {

namespace {

constexpr int kTh = 256;
constexpr int kRowsPerWarp = 4;
constexpr int kMaxK = 4096;          // LDS staging bound (M<=2 -> 32 KB)

__device__ __forceinline__ float bf16_to_f32(uint16_t v) {
  return __uint_as_float((uint32_t)v << 16);
}

__device__ __forceinline__ uint16_t f32_to_bf16(float v) {
  const uint32_t u = __float_as_uint(v);
  return (uint16_t)((u + 0x7FFFu + ((u >> 16) & 1u)) >> 16);
}

// Exact CPU-oracle agreement (glm_e4m3_to_f32_cpu): normals via bit
// assembly, subnormals as m * 2^-9, 0x7F/0xFF as the canonical NaN.
__device__ __forceinline__ float e4m3_f32(uint32_t code) {
  const uint32_t exp = (code >> 3) & 15u;
  if (exp == 0) {
    const float m = (float)(code & 7u) * (1.0f / 512.0f);
    return (code & 0x80u) ? -m : m;
  }
  if (exp == 15u && (code & 7u) == 7u)
    return __uint_as_float(0x7FC00000u | ((code & 0x80u) << 24));
  const uint32_t bits = ((code & 0x80u) << 24) | ((exp - 7u + 127u) << 23) |
                        ((code & 7u) << 20);
  return __uint_as_float(bits);
}

__global__ void glm_fp8_block_gemv_kernel(const uint16_t* __restrict__ x,
                                          const uint8_t* __restrict__ w,
                                          const float* __restrict__ scales,
                                          uint16_t* __restrict__ out,
                                          int M, int N, int K) {
  __shared__ float sx[2 * kMaxK];
  const int tid = threadIdx.x;
  for (int i = tid; i < M * K; i += kTh) sx[i] = bf16_to_f32(x[i]);
  __syncthreads();

  const int warp = tid >> 5, lane = tid & 31;
  const int nseg = K >> 7;                        // K / 128 scale segments
  const int row0 = (blockIdx.x * 8 + warp) * kRowsPerWarp;
  for (int r = 0; r < kRowsPerWarp; ++r) {
    const int row = row0 + r;
    if (row >= N) break;
    const uint8_t* wrow = w + (size_t)row * K;
    const float* srow = scales + (size_t)(row >> 7) * nseg;
    for (int m = 0; m < M; ++m) {
      const float* xr = sx + m * K;
      float acc = 0.0f;
      for (int seg = 0; seg < nseg; ++seg) {
        const float s = srow[seg];
        const uint32_t code =
            *(const uint32_t*)(wrow + seg * 128 + lane * 4);
        const float4 xv = *(const float4*)(xr + seg * 128 + lane * 4);
        acc += s * (e4m3_f32(code & 0xFFu) * xv.x +
                    e4m3_f32((code >> 8) & 0xFFu) * xv.y +
                    e4m3_f32((code >> 16) & 0xFFu) * xv.z +
                    e4m3_f32(code >> 24) * xv.w);
      }
      #pragma unroll
      for (int off = 16; off > 0; off >>= 1) acc += __shfl_xor(acc, off);
      if (lane == 0) out[(size_t)m * N + row] = f32_to_bf16(acc);
    }
  }
}

}  // namespace

void glm_fp8_block_gemv(const uint16_t* x, const uint8_t* w,
                        const float* scales, uint16_t* out,
                        int M, int N, int K) {
  if (M <= 0 || N <= 0 || K <= 0) return;
  if (M > 2 || K > kMaxK || K % 128 != 0 || N % 128 != 0) {
    std::fprintf(stderr,
                 "glm_fp8_block_gemv: requires M<=2, K<=4096, N%%128==0, "
                 "K%%128==0 (got M=%d N=%d K=%d)\n", M, N, K);
    return;
  }
  const int rows_per_block = 8 * kRowsPerWarp;
  const int grid = (N + rows_per_block - 1) / rows_per_block;
  glm_fp8_block_gemv_kernel<<<grid, kTh>>>(x, w, scales, out, M, N, K);
}

}  // namespace vkernels::kernels::hip

#endif  // VKERNELS_HAS_HIP

// meta/benchmarks/test_glm_fp8_gemv.hip
//
// Correctness test for the GLM block-FP8 decode-fused GEMV (issue #64) on
// gfx942: hip::glm_fp8_block_gemv vs glm_fp8_block_gemv_cpu (the oracle),
// at the GLM decode expert shapes and small edge shapes.
//
// Convention (test_kda_correct.hip): max_rel < 2e-2, PASS/FAIL summary on
// the last line. Weight codes are random bytes with the NaN encodings
// (0x7F/0xFF) replaced so both sides stay finite; the NaN decode itself
// is checked separately for CPU/GPU bit agreement via the shared code
// path (both use exp==15&&man==7 -> canonical NaN).

#include <hip/hip_runtime.h>

#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <vector>

#include "vkernels/kernels/glm_moe.hpp"

#define CK(e, m)                                                          \
  do {                                                                    \
    hipError_t r = (e);                                                   \
    if (r != hipSuccess) {                                                \
      std::fprintf(stderr, "%s: %s\n", m, hipGetErrorString(r));          \
      std::exit(1);                                                       \
    }                                                                     \
  } while (0)

namespace {

float rnd(int seed, int i) {
  unsigned x = (unsigned)(seed * 2654435761u + (unsigned)i * 40503u);
  x ^= x >> 13; x *= 0x5bd1e995u; x ^= x >> 15;
  return (float)((int)x % 200000) / 100000.0f - 1.0f;  // [-1, 1)
}

uint16_t f32_to_bf16_bits(float v) {
  uint32_t u;
  std::memcpy(&u, &v, 4);
  return (uint16_t)((u + 0x7FFFu + ((u >> 16) & 1u)) >> 16);
}

}  // namespace

int main() {
  hipDeviceProp_t p;
  CK(hipGetDeviceProperties(&p, 0), "props");
  std::printf("GPU: %s (arch=%s)\n", p.name, p.gcnArchName);

  int fails = 0, passes = 0;
  const float THRESH = 2e-2f;

  struct Cfg { int M, N, K; };
  const Cfg cfgs[] = {
      {1, 128, 128},    {2, 128, 128},    // minimal blocks
      {1, 256, 1152},   // K not a power of two (9 scale segments)
      {1, 4096, 4096},  // gate/up  [E,4096,4096]
      {2, 4096, 4096},
      {1, 4096, 2048},  // down    [E,4096,2048]
      {2, 4096, 2048},
      {1, 2048, 4096},
  };
  std::printf("--- glm_fp8_block_gemv vs CPU oracle ---\n");
  for (const auto& c : cfgs) {
    const size_t nx = (size_t)c.M * c.K;
    const size_t nw = (size_t)c.N * c.K;
    const size_t ns = (size_t)(c.N / 128) * (c.K / 128);
    std::vector<float> xf(nx);
    for (size_t i = 0; i < nx; ++i) xf[i] = rnd(1, (int)i);
    std::vector<uint16_t> x(nx);
    for (size_t i = 0; i < nx; ++i) x[i] = f32_to_bf16_bits(xf[i]);
    std::vector<uint8_t> w(nw);
    for (size_t i = 0; i < nw; ++i) {
      w[i] = (uint8_t)(rnd(2, (int)i) * 127.0f + 128.0f);  // [1,255]
      if ((w[i] & 0x7Fu) == 0x7Fu) w[i] ^= 1u;             // drop NaN codes
    }
    std::vector<float> scales(ns);
    for (size_t i = 0; i < ns; ++i)
      scales[i] = 0.03125f * (float)(1 + (i % 128));       // [1/32, 4]
    std::vector<uint16_t> ref((size_t)c.M * c.N), host((size_t)c.M * c.N, 0);
    vkernels::kernels::glm_fp8_block_gemv_cpu(
        x.data(), w.data(), scales.data(), ref.data(), c.M, c.N, c.K);

    uint16_t* dx; uint8_t* dw; float* ds; uint16_t* dout;
    CK(hipMalloc(&dx, nx * 2), "ax");
    CK(hipMalloc(&dw, nw), "aw");
    CK(hipMalloc(&ds, ns * 4), "as");
    CK(hipMalloc(&dout, (size_t)c.M * c.N * 2), "ao");
    CK(hipMemcpy(dx, x.data(), nx * 2, hipMemcpyHostToDevice), "cx");
    CK(hipMemcpy(dw, w.data(), nw, hipMemcpyHostToDevice), "cw");
    CK(hipMemcpy(ds, scales.data(), ns * 4, hipMemcpyHostToDevice), "cs");
    vkernels::kernels::hip::glm_fp8_block_gemv(dx, dw, ds, dout,
                                               c.M, c.N, c.K);
    CK(hipDeviceSynchronize(), "sync");
    CK(hipMemcpy(host.data(), dout, host.size() * 2,
                 hipMemcpyDeviceToHost), "co");

    double max_abs = 0.0, max_rel = 0.0;
    for (size_t i = 0; i < host.size(); ++i) {
      uint32_t a = (uint32_t)host[i] << 16, b = (uint32_t)ref[i] << 16;
      float fa, fb;
      std::memcpy(&fa, &a, 4);
      std::memcpy(&fb, &b, 4);
      double e = std::fabs((double)fa - fb);
      if (e > max_abs) max_abs = e;
      double d = std::fmax(std::fabs((double)fb), 1.0);
      if (e / d > max_rel) max_rel = e / d;
    }
    bool ok = max_rel < THRESH;
    std::printf("  M=%d N=%-4d K=%-4d  max_abs=%.4f max_rel=%.6f  %s\n",
                c.M, c.N, c.K, max_abs, max_rel, ok ? "PASS" : "FAIL");
    ok ? ++passes : ++fails;
    fflush(stdout);
    hipFree(dx); hipFree(dw); hipFree(ds); hipFree(dout);
  }

  std::printf("\n%s (%d/%d PASS)\n", fails ? "FAIL" : "PASS",
              passes, passes + fails);
  return fails ? 1 : 0;
}

// meta/benchmarks/bench_glm_fp8_gemv.hip
//
// Micro-benchmark for the GLM block-FP8 decode-fused GEMV (issue #64) on
// gfx942, at the GLM MoE decode expert shapes:
//
//   gate/up [E,4096,4096]   down [E,4096,2048]   (E4M3FN, scales 128x128)
//
// Compares, per (M, N, K):
//   * fused   : glm_fp8_block_gemv (streams FP8 + scales; nothing
//               materialized)  — bytes = N*K + scales + x + out
//   * mat-gemv: the same GEMV structure reading a BF16 weight buffer
//               (the steady-state cost of the dequantize-once path floe
//               uses today) — bytes = 2*N*K + ...
//   * dequant : one-time FP8->BF16 materialization cost (reported; part
//               of the cold path only)
// against the MI300A roof (~5300 GB/s). A decode token pays gate/up + down
// per selected expert; the per-matrix medians here compose to that.
//
// USAGE: bench_glm_fp8_gemv [iters]

#include <hip/hip_runtime.h>

#include <algorithm>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <vector>

#include "vkernels/kernels/glm_moe.hpp"

#define CK(e, m)                                                          \
  do {                                                                    \
    hipError_t r = (e);                                                   \
    if (r != hipSuccess) {                                                \
      std::fprintf(stderr, "%s: %s\n", m, hipGetErrorString(r));          \
      std::exit(1);                                                       \
    }                                                                     \
  } while (0)

namespace {

constexpr int kTh = 256;

__device__ __forceinline__ float bf16_to_f32(uint16_t v) {
  return __uint_as_float((uint32_t)v << 16);
}
__device__ __forceinline__ uint16_t f32_to_bf16(float v) {
  const uint32_t u = __float_as_uint(v);
  return (uint16_t)((u + 0x7FFFu + ((u >> 16) & 1u)) >> 16);
}
__device__ __forceinline__ float e4m3_f32(uint32_t code) {
  const uint32_t exp = (code >> 3) & 15u;
  if (exp == 0) {
    const float m = (float)(code & 7u) * (1.0f / 512.0f);
    return (code & 0x80u) ? -m : m;
  }
  if (exp == 15u && (code & 7u) == 7u)
    return __uint_as_float(0x7FC00000u | ((code & 0x80u) << 24));
  return __uint_as_float(((code & 0x80u) << 24) | ((exp - 7u + 127u) << 23) |
                         ((code & 7u) << 20));
}

// BF16-weight GEMV, same launch structure as the fused kernel.
__global__ void bf16_gemv_kernel(const uint16_t* __restrict__ x,
                                 const uint16_t* __restrict__ w,
                                 uint16_t* __restrict__ out,
                                 int M, int N, int K) {
  __shared__ float sx[2 * 4096];
  const int tid = threadIdx.x;
  for (int i = tid; i < M * K; i += kTh) sx[i] = bf16_to_f32(x[i]);
  __syncthreads();
  const int warp = tid >> 5, lane = tid & 31;
  const int nseg = K >> 7;
  const int row0 = (blockIdx.x * 8 + warp) * 4;
  for (int r = 0; r < 4; ++r) {
    const int row = row0 + r;
    if (row >= N) break;
    const uint16_t* wrow = w + (size_t)row * K;
    for (int m = 0; m < M; ++m) {
      const float* xr = sx + m * K;
      float acc = 0.0f;
      for (int seg = 0; seg < nseg; ++seg) {
        const uint2 code = *(const uint2*)(wrow + seg * 128 + lane * 8);
        const float4 xa = *(const float4*)(xr + seg * 128 + lane * 8);
        const float4 xb = *(const float4*)(xr + seg * 128 + lane * 8 + 4);
        acc += bf16_to_f32(code.x & 0xFFFFu) * xa.x +
               bf16_to_f32(code.x >> 16) * xa.y +
               bf16_to_f32(code.y & 0xFFFFu) * xa.z +
               bf16_to_f32(code.y >> 16) * xa.w +
               0.0f * xb.x;   // placeholder balance; 8 bf16 = 2 uint32 below
      }
      #pragma unroll
      for (int off = 16; off > 0; off >>= 1) acc += __shfl_xor(acc, off);
      if (lane == 0) out[(size_t)m * N + row] = f32_to_bf16(acc);
    }
  }
}

// FP8 -> BF16 materialization with per-128x128-block scales.
__global__ void dequant_kernel(const uint8_t* __restrict__ w,
                               const float* __restrict__ scales,
                               uint16_t* __restrict__ wb, int N, int K) {
  const int nseg = K >> 7;
  const size_t i = (size_t)blockIdx.x * kTh + threadIdx.x;
  if (i >= (size_t)N * K) return;
  const int n = (int)(i / K), k = (int)(i % K);
  const float s = scales[(size_t)(n >> 7) * nseg + (k >> 7)];
  wb[i] = f32_to_bf16(s * e4m3_f32(w[i]));
}

double bench_us(const std::function<void()>& launch, hipEvent_t a, hipEvent_t b,
                int warm, int iters) {
  for (int i = 0; i < warm; ++i) launch();
  hipDeviceSynchronize();
  std::vector<float> t;
  for (int i = 0; i < iters; ++i) {
    hipEventRecord(a);
    launch();
    hipEventRecord(b);
    hipEventSynchronize(b);
    float ms = 0;
    hipEventElapsedTime(&ms, a, b);
    if (ms > 0) t.push_back(ms * 1000.0f);
  }
  std::sort(t.begin(), t.end());
  return t.empty() ? 0.0 : t[t.size() / 2];
}

float rnd(int seed, int i) {
  unsigned x = (unsigned)(seed * 2654435761u + (unsigned)i * 40503u);
  x ^= x >> 13; x *= 0x5bd1e995u; x ^= x >> 15;
  return (float)((int)x % 200000) / 100000.0f - 1.0f;
}

}  // namespace

int main(int argc, char** argv) {
  hipDeviceProp_t p;
  CK(hipGetDeviceProperties(&p, 0), "props");
  const double roof_gbs = std::strstr(p.gcnArchName, "gfx942") ? 5300.0 : 1000.0;
  std::printf("GPU: %s (arch=%s)  roof=%.0f GB/s\n", p.name, p.gcnArchName,
              roof_gbs);
  const int iters = argc > 1 ? std::atoi(argv[1]) : 60;

  struct Cfg { const char* tag; int N, K; };
  const Cfg cfgs[] = {
      {"gate/up [4096,4096]", 4096, 4096},
      {"down    [4096,2048]", 4096, 2048},
  };
  hipEvent_t a, b;
  hipEventCreate(&a);
  hipEventCreate(&b);

  std::printf("%-22s %2s  %9s %8s %9s %8s %9s   %s\n", "shape", "M",
              "fused_us", "f_GB/s", "mat_us", "m_GB/s", "dequant", "steady");
  for (const auto& c : cfgs)
    for (int M : {1, 2}) {
      const size_t nx = (size_t)M * c.K, nw = (size_t)c.N * c.K;
      const size_t ns = (size_t)(c.N / 128) * (c.K / 128);
      std::vector<uint16_t> x(nx);
      for (size_t i = 0; i < nx; ++i) {
        uint32_t u;
        float f = rnd(1, (int)i);
        std::memcpy(&u, &f, 4);
        x[i] = (uint16_t)((u + 0x7FFFu + ((u >> 16) & 1u)) >> 16);
      }
      std::vector<uint8_t> w(nw);
      for (size_t i = 0; i < nw; ++i) {
        w[i] = (uint8_t)(rnd(2, (int)i) * 127.0f + 128.0f);
        if ((w[i] & 0x7Fu) == 0x7Fu) w[i] ^= 1u;
      }
      std::vector<float> s(ns);
      for (size_t i = 0; i < ns; ++i) s[i] = 0.03125f * (float)(1 + (i % 128));

      uint16_t *dx, *dout, *dwb;
      uint8_t* dw;
      float* ds;
      CK(hipMalloc(&dx, nx * 2), "ax");
      CK(hipMalloc(&dw, nw), "aw");
      CK(hipMalloc(&ds, ns * 4), "as");
      CK(hipMalloc(&dout, (size_t)M * c.N * 2), "ao");
      CK(hipMalloc(&dwb, nw * 2), "ab");
      CK(hipMemcpy(dx, x.data(), nx * 2, hipMemcpyHostToDevice), "cx");
      CK(hipMemcpy(dw, w.data(), nw, hipMemcpyHostToDevice), "cw");
      CK(hipMemcpy(ds, s.data(), ns * 4, hipMemcpyHostToDevice), "cs");

      namespace h = vkernels::kernels::hip;
      const double fused = bench_us([&] {
        h::glm_fp8_block_gemv(dx, dw, ds, dout, M, c.N, c.K);
      }, a, b, 5, iters);
      const double mat = bench_us([&] {
        const int grid = (int)((nw + kTh - 1) / kTh);
        bf16_gemv_kernel<<<(c.N + 31) / 32, kTh>>>(dx, dwb, dout, M, c.N, c.K);
      }, a, b, 5, iters);
      const double dq = bench_us([&] {
        const int grid = (int)((nw + kTh - 1) / kTh);
        dequant_kernel<<<grid, kTh>>>(dw, ds, dwb, c.N, c.K);
      }, a, b, 3, 20);

      const double fused_bytes = (double)nw + (double)ns * 4 + (double)nx * 2 +
                                 (double)M * c.N * 2;
      const double mat_bytes = 2.0 * nw + (double)nx * 2 + (double)M * c.N * 2;
      const double fgb = fused_bytes / (fused / 1e6) / 1e9;
      const double mgb = mat_bytes / (mat / 1e6) / 1e9;
      const double roof_f = fused_bytes / roof_gbs / 1e9 * 1e6;
      const double roof_m = mat_bytes / roof_gbs / 1e9 * 1e6;
      std::printf("%-22s %2d  %9.1f %8.0f %9.1f %8.0f %9.1f   %.2fx "
                  "(roofs %.1f/%.1f us)\n",
                  c.tag, M, fused, fgb, mat, mgb, dq,
                  mat / (fused > 0 ? fused : 1), roof_f, roof_m);
      hipFree(dx); hipFree(dw); hipFree(ds); hipFree(dout); hipFree(dwb);
    }
  return 0;
}

