"""Real MI300A expert decode: fused FP8 GEMV vs gather-dequant + einsum."""

import argparse
import json
import time

import torch

from floe.engine.runner.kernels.fp8_experts import gather_dequant
from floe.engine.runner.kernels.glm5_fp8_gemv import expert_gemv


@torch.inference_mode()
def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--iterations", type=int, default=30)
    parser.add_argument("--tokens", type=int, choices=(1, 2), default=1)
    args = parser.parse_args()
    torch.manual_seed(892)
    results = {}
    for name, o, i, broadcast in (("gate_up", 4096, 4096, True), ("down", 4096, 2048, False)):
        raw = torch.randint(0, 256, (288, o, i), device="cuda", dtype=torch.uint8)
        raw.masked_fill_((raw & 127) == 127, 0)
        weights = raw.view(torch.float8_e4m3fn)
        scales = 0.0005 + torch.rand((288, o // 128, i // 128), device="cuda") * 0.001
        indices = torch.rand((args.tokens, 288), device="cuda").topk(8, dim=-1).indices
        x = torch.randn((args.tokens, i) if broadcast else (args.tokens, 8, i), device="cuda", dtype=torch.bfloat16)

        def baseline():
            selected = gather_dequant(weights, scales, indices)
            return torch.einsum("ti,tkoi->tko" if broadcast else "tki,tkoi->tko", x, selected)

        def fused():
            return expert_gemv(x, weights, scales, indices)

        reference, actual = baseline(), fused()
        difference = actual.float() - reference.float()
        result = {"max_abs_error": difference.abs().max().item(), "relative_l2_error": (difference.norm() / reference.float().norm()).item()}
        if not torch.isfinite(actual).all() or result["relative_l2_error"] > 0.003:
            raise RuntimeError(f"GEMV parity failed for {name}: {result}")
        for variant, fn in (("gather_einsum", baseline), ("gemv", fused)):
            for _ in range(3):
                fn()
            torch.cuda.synchronize()
            torch.cuda.reset_peak_memory_stats()
            memory = torch.cuda.memory_allocated()
            start = time.perf_counter()
            for _ in range(args.iterations):
                fn()
            torch.cuda.synchronize()
            result[variant] = {"ms": (time.perf_counter() - start) * 1000 / args.iterations, "temporary_MiB": (torch.cuda.max_memory_allocated() - memory) / 2**20}
        result["speedup"] = result["gather_einsum"]["ms"] / result["gemv"]["ms"]
        results[name] = result
        print(json.dumps({name: result}), flush=True)
        del raw, weights, scales, x, indices, reference, actual, difference
    print(json.dumps(results, indent=2), flush=True)


if __name__ == "__main__":
    main()

